#include "M1Audit.h"
#include "Geometry.h"
#include <QDateTime>
#include <algorithm>
#include <cmath>
#include <map>
#include <set>
#include <regex>
#include <stdexcept>
namespace spacerad::engine {
namespace {
void require(bool b,const char* m){if(!b)throw std::runtime_error(std::string("M1: ")+m);}
void fields(const Json& j,const std::set<std::string>& keys){require(j.is_object()&&j.size()==keys.size(),"missing/extra fields");for(auto it=j.begin();it!=j.end();++it)require(keys.count(it.key()),"unknown field");}
std::string text(const Json& v,std::size_t max=4000){require(v.is_string(),"text required");auto s=v.get<std::string>();require(!s.empty()&&s.size()<=max&&!QString::fromStdString(s).trimmed().isEmpty(),"empty/oversized text");return s;}
double real(const Json& v,double lo=0,double hi=1e300){require(v.is_number(),"number required");double x=v.get<double>();require(std::isfinite(x)&&x>=lo&&x<=hi,"number outside finite range");return x;}
int integer(const Json& v,int lo=2,int hi=100000000){require(v.is_number_integer(),"integer required");auto x=v.get<std::int64_t>();require(x>=lo&&x<=hi,"integer outside range");return int(x);}
Json comparable(const Project& p){auto j=p.toJson();for(const char* k:{"schema","name","provenance","events","seed"})j.erase(k);auto& env=j["environment"];env.erase("source");env.erase("metadata");for(auto& s:env["spectra"])s.erase("provenance");return j;}
Json sensitive(const Project& p){Json j=Json::object();auto geometry=geometrySnapshot(p);for(const auto& v:geometry.at("volumes"))if(v.at("sensitive")==true)j[v.at("id").get<std::string>()]={{"material",v.at("material")},{"center",v.at("world_center_mm")},{"rotation",v.at("world_rotation")},{"volume",v.at("material_volume_mm3")}};return j;}
bool isolated(const Project& a,const Project& b,const std::string& category){auto x=comparable(a),y=comparable(b);if(x==y)return false;if(category=="physics"){x.erase("physics_list");y.erase("physics_list");x.erase("production_cut_mm");y.erase("production_cut_mm");}
    else if(category=="source"){x.erase("source_radius_mm");y.erase("source_radius_mm");}
    else{if(sensitive(a)!=sensitive(b))return false;for(const char* k:{"volumes","assemblies","templates","instances","material_snapshot","material_contract","geometry_contract","instance_contract"}){x.erase(k);y.erase(k);}}
    return x==y;
}
const Json* target(const Json& r,const std::string& id){for(const auto& t:r.at("targets"))if(t.at("id")==id)return &t;return nullptr;}
std::set<int> seeds(const M1Run& r){std::set<int> out;if(r.result.contains("batch")){for(const auto& b:r.result.at("batch").at("batches"))if(b.at("status")=="completed")require(out.insert(integer(b.at("seed"),1,2147483646)).second,"duplicate batch seed");}else if(r.result.at("histories").get<int>()>0)out.insert(int(r.project.seed));return out;}
bool stats(const M1Run& r,const Json& criterion){auto t=target(r.result,criterion.at("id"));if(!t)return false;int n=integer(r.result.at("histories"),0);int nz=integer(t->at("nonzero_histories"),0,n);double d=real(t->at("tid_Gy"));real(t->at("tid_standard_error_Gy"));real(t->at("mass_kg"),1e-300);
    return r.result.at("status")=="completed"&&n>0&&d>0&&nz>=criterion.at("min_nonzero_histories").get<int>()&&!t->at("relative_standard_error").is_null()&&real(t->at("relative_standard_error"))<=criterion.at("max_relative_error").get<double>()&&n<=criterion.at("max_histories").get<int>()&&r.project.events<=criterion.at("max_histories").get<int>();
}
bool digest(const Json& v){return v.is_string()&&std::regex_match(v.get<std::string>(),std::regex("[a-f0-9]{64}"));}
}
Json validateM1Plan(const Json& j){fields(j,{"schema","name","baseline_job","targets","reviews","sensitivity"});require(j.at("schema")=="scdat.radiation-m1-plan/1","unsupported plan schema");text(j.at("name"),200);text(j.at("baseline_job"));
    const auto& targets=j.at("targets");require(targets.is_array()&&!targets.empty()&&targets.size()<=128,"require 1..128 target criteria");std::set<std::string> ids;
    for(const auto& t:targets){fields(t,{"id","min_nonzero_histories","max_relative_error","max_histories"});require(ids.insert(text(t.at("id"),128)).second,"duplicate target criteria");integer(t.at("min_nonzero_histories"));integer(t.at("max_histories"));real(t.at("max_relative_error"),1e-9,1);}
    fields(j.at("reviews"),{"environment","geometry","physics","source"});for(const auto& key:{"environment","geometry","physics","source"}){const auto& r=j.at("reviews").at(key);if(r.is_null())continue;fields(r,{"reviewer","reviewed_utc","notes","files"});text(r.at("reviewer"),200);text(r.at("notes"));auto utc=text(r.at("reviewed_utc"),20);auto dt=QDateTime::fromString(QString::fromStdString(utc),Qt::ISODate);require(dt.isValid()&&dt.toUTC().toString("yyyy-MM-dd'T'HH:mm:ss'Z'").toStdString()==utc,"review timestamp must be valid YYYY-MM-DDTHH:MM:SSZ");
        require(r.at("files").is_array()&&!r.at("files").empty()&&r.at("files").size()<=8,"require 1..8 review attachments");std::set<std::string> paths;for(const auto& f:r.at("files")){fields(f,{"path","role"});require(paths.insert(text(f.at("path"))).second,"duplicate review attachment path");auto role=text(f.at("role"),40);require(std::string(key)=="environment"?(role=="spectrum"||role=="model_report"):role==std::string(key)+"_review","unsupported attachment role");}}
    require(j.at("sensitivity").is_array()&&j.at("sensitivity").size()<=12,"at most 12 sensitivity cases");ids.clear();for(const auto& c:j.at("sensitivity")){fields(c,{"id","category","job_directory","max_relative_change"});auto id=text(c.at("id"),48);require(std::regex_match(id,std::regex("[A-Za-z0-9][A-Za-z0-9_-]*"))&&ids.insert(id).second,"invalid/duplicate sensitivity ID");auto category=text(c.at("category"),16);require(category=="physics"||category=="geometry"||category=="source","unknown sensitivity category");text(c.at("job_directory"));real(c.at("max_relative_change"),0,10);}return j;
}
Json draftM1Plan(const Project& p,const std::string& job){Json targets=Json::array();auto geometry=geometrySnapshot(p);for(const auto& v:geometry.at("volumes"))if(v.at("sensitive")==true)targets.push_back({{"id",v.at("id")},{"min_nonzero_histories",30},{"max_relative_error",.1},{"max_histories",p.events}});
    return validateM1Plan({{"schema","scdat.radiation-m1-plan/1"},{"name",p.name+" M1 preparation"},{"baseline_job",job},{"targets",targets},{"reviews",{{"environment",nullptr},{"geometry",nullptr},{"physics",nullptr},{"source",nullptr}}},{"sensitivity",Json::array()}});
}
Json evaluateM1(const Json& raw,const std::vector<M1Run>& runs,const Json& attachments){auto plan=validateM1Plan(raw);require(runs.size()==plan.at("sensitivity").size()+1,"run/case count differs");const auto& base=runs.front();for(const auto& r:runs){r.project.validate();require(r.result.at("schema")=="scdat.radiation-result/2"&&r.result.at("targets").is_array(),"unsupported transport result");auto project=Project::fromJson(r.result.at("project")).toJson(),expected=r.project.toJson();project.erase("provenance");expected.erase("provenance");require(project==expected,"embedded physical project differs");require(real(r.result.at("expected_primaries"))==r.project.expectedPrimaries(),"exposure identity differs");}
    Json gates=Json::array(),targetChecks=Json::array(),sensitivityChecks=Json::array();auto add=[&](const std::string& id,bool ok,const std::string& detail,const std::string& kind="machine"){gates.push_back({{"id",id},{"passed",ok},{"kind",kind},{"detail",detail}});};
    const auto& p=base.project;auto signature=sensitive(p);add("multiple_targets",signature.size()>=2,"M1 preparation requires at least two sensitive targets");std::set<std::string> requested,actual;for(const auto& c:plan.at("targets"))requested.insert(c.at("id"));for(auto it=signature.begin();it!=signature.end();++it)actual.insert(it.key());add("target_coverage",requested==actual,"Criteria must name every sensitive target exactly once");
    add("baseline_complete",base.result.at("status")=="completed"&&integer(base.result.at("histories"),0)>0,"Completed transport histories required");add("reproducible_reports",std::all_of(runs.begin(),runs.end(),[](const M1Run& r){return r.report.at("replay").at("eligible")==true;}),"Every run needs replay-eligible evidence");
    add("environment_non_synthetic",!p.synthetic,"Synthetic input cannot support mission readiness");add("environment_metadata_complete",p.missingEnvironmentMetadata().empty(),"Model, orbit, epoch, interval and statistical metadata must be complete");
    bool filesBound=true;const auto& envReview=plan.at("reviews").at("environment");std::set<std::string> sourceHashes,reportHashes;for(const auto& key:{"environment","geometry","physics","source"}){const auto& r=plan.at("reviews").at(key);bool declared=!r.is_null();if(declared)for(const auto& f:r.at("files")){auto path=f.at("path").get<std::string>();bool exists=attachments.contains(path)&&digest(attachments.at(path).at("sha256"))&&integer(attachments.at(path).at("size_bytes"),1,32*1024*1024)>0;declared=declared&&exists;if(exists&&std::string(key)=="environment"){auto hash=attachments.at(path).at("sha256").get<std::string>();if(f.at("role")=="spectrum")sourceHashes.insert(hash);else reportHashes.insert(hash);}}
        add(std::string(key)+"_review_declared",declared,"Reviewer/time/notes and attachment bytes are a declaration, not authenticated approval","declaration");}
    if(envReview.is_null()||sourceHashes.empty()||reportHashes.empty())filesBound=false;for(const auto& hash:reportHashes)if(sourceHashes.count(hash))filesBound=false;
    for(const auto& s:p.spectra){const auto& source=s.provenance.at("source_file");bool found=false;if(!source.is_null()&&!envReview.is_null())for(const auto& f:envReview.at("files"))if(f.at("role")=="spectrum"){auto path=f.at("path").get<std::string>();if(attachments.contains(path)&&source.at("sha256")==attachments.at(path).at("sha256")&&source.at("size_bytes")==attachments.at(path).at("size_bytes"))found=true;}filesBound=filesBound&&found;}add("environment_files_bound",filesBound,"Raw source SHA/size must match every spectrum; a separate model report is required");
    bool baselineStats=true;for(const auto& c:plan.at("targets")){bool ok=stats(base,c);baselineStats=baselineStats&&ok;auto t=target(base.result,c.at("id"));targetChecks.push_back({{"id",c.at("id")},{"passed",ok},{"criterion",c},{"result",t?*t:Json(nullptr)},{"requested_histories",p.events},{"completed_histories",base.result.at("histories")}});}add("baseline_statistics",baselineStats,"Per-target hit/RSE criteria and requested/actual history budgets must all pass");
    bool sameRuntime=base.result.contains("worker")&&digest(base.result.at("worker").at("sha256"))&&base.result.at("runtime_audit").is_object(),distinct=true;std::set<int> used;
    for(const auto& r:runs){if(!sameRuntime||!r.result.contains("worker")||r.result.at("worker").at("sha256")!=base.result.at("worker").at("sha256")||r.result.at("runtime_audit")!=base.result.at("runtime_audit"))sameRuntime=false;auto set=seeds(r);if(set.empty())distinct=false;for(int seed:set)if(!used.insert(seed).second)distinct=false;}
    add("same_runtime",sameRuntime,"All transport runs must share Worker SHA and runtime audit");add("distinct_seeds",distinct,"Completed-history seed sets must be pairwise disjoint; no mathematical PRNG independence proof");
    std::map<std::string,bool> categories;std::map<std::string,int> counts;for(const auto& key:{"physics","geometry","source"}){categories[key]=true;counts[key]=0;}
    for(std::size_t i=1;i<runs.size();++i){const auto& c=plan.at("sensitivity")[i-1];const auto& run=runs[i];auto category=c.at("category").get<std::string>();++counts[category];bool iso=isolated(p,run.project,category),all=iso&&sameRuntime&&distinct;
        for(const auto& criterion:plan.at("targets")){auto id=criterion.at("id").get<std::string>();auto b=target(base.result,id),v=target(run.result,id);bool valid=b&&v&&stats(base,criterion)&&stats(run,criterion)&&b->at("mass_kg")==v->at("mass_kg")&&iso&&sameRuntime&&distinct;Json change=nullptr,envelope=nullptr;
            if(valid){double d0=real(b->at("tid_Gy"),1e-300),d1=real(v->at("tid_Gy")),se0=real(b->at("tid_standard_error_Gy")),se1=real(v->at("tid_standard_error_Gy"));double delta=std::abs(d1-d0)/d0,band=delta+2*std::hypot(se0,se1)/d0;require(std::isfinite(delta)&&std::isfinite(band),"sensitivity ratio overflow");change=delta;envelope=band;valid=band<=c.at("max_relative_change").get<double>();}
            all=all&&valid;sensitivityChecks.push_back({{"case_id",c.at("id")},{"category",category},{"target_id",id},{"isolated_change",iso},{"passed",valid},{"baseline_dose_Gy",b?b->at("tid_Gy"):Json(nullptr)},{"case_dose_Gy",v?v->at("tid_Gy"):Json(nullptr)},{"relative_change",change},{"screening_envelope",envelope},{"max_relative_change",c.at("max_relative_change")}});
        }categories[category]=categories[category]&&all;add("case:"+c.at("id").get<std::string>(),all,"Isolated declared change, same exposure/targets/runtime, disjoint seeds, sufficient statistics and screening limit");}
    for(const auto& key:{"physics","geometry","source"})add(std::string("sensitivity_")+key,counts[key]>0&&categories[key],"At least one valid case in this category; all declared cases must pass");
    Json runSummaries=Json::array();for(std::size_t i=0;i<runs.size();++i){const auto& r=runs[i];runSummaries.push_back({{"id",i==0?Json("baseline"):plan.at("sensitivity")[i-1].at("id")},{"job_status",r.result.at("status")},{"requested_histories",r.project.events},{"completed_histories",r.result.at("histories")},{"original_statistical_state",r.report.value("summary",Json::object()).value("statistical_state",Json(nullptr))},{"original_criterion",r.report.value("statistics",Json::object()).value("criterion",Json(nullptr))}});}
    Json blockers=Json::array();for(const auto& g:gates)if(g.at("passed")==false)blockers.push_back(g.at("id"));return {{"schema","scdat.radiation-m1-audit/1"},{"name",plan.at("name")},{"readiness",blockers.empty()?"ready_for_review":"incomplete"},{"m1_accepted",false},{"human_decision_required",true},{"external_physics_validated",false},{"gates",gates},{"blocking_gates",blockers},{"target_checks",targetChecks},{"sensitivity_checks",sensitivityChecks},{"run_summaries",runSummaries},{"statistics_policy","Evaluate M1 plan per-target thresholds and budgets; original task stopping criteria/state are retained separately, not a second automatic gate"},{"screening_rule","(abs(Di-D0)+2*hypot(SE0,SEi))/D0; engineering MC screening only, not a confidence coverage guarantee"},{"limitations",Json::array({"Declarations and hashes do not authenticate reviewers, mission data or physical validity","Source sensitivity currently varies only source-sphere radius; angular or environment-model alternatives require further work","Distinct seeds do not prove independent PRNG streams; adaptive stopping coverage is not validated","ready_for_review never automatically accepts M1; formal engineering review remains necessary"})}};
}
}
